/**
 * Jinx Lil' Monsta + Scarlet Woman: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Lil%27_Monsta
 * Wiki: https://wiki.bloodontheclocktower.com/Scarlet_Woman
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L116). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { becomesOffer } from '#lib/core/rules/becomes.ts';
import { gameEnds } from '#lib/core/rules/game-end.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { reminderTargetMisses } from '#lib/core/rules/reminder-targets.ts';
import { babysits, babysitter, withLilMonsta } from './lilmonsta.test-support.ts';

describe("Lil' Monsta + Scarlet Woman jinx", () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'lilmonsta', 'scarletwoman');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('lilmonsta')?.name).toBe("Lil' Monsta");
		expect(data.byId.get('scarletwoman')?.name).toBe('Scarlet Woman');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['lilmonsta', 'scarletwoman'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['lilmonsta'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['scarletwoman'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: the Scarlet Woman catches Lil' Monsta rather than becoming a
	// Demon, and keeps it. Marked with her Is The Demon, she is the only fit for Lil' Monsta's
	// Is The Demon from then on; anyone else is faded and warned (warn, never lock).
	describe('the Scarlet Woman babysits Lil’ Monsta for the rest of the game', () => {
		const cast = ['scarletwoman', 'poisoner', 'chef', 'empath', 'monk', 'mayor', 'soldier'];
		const base = babysits(withLilMonsta(cast), 'poisoner').newDay();
		const misses = (s: typeof base, on: string) =>
			reminderTargetMisses(s.game, babysitter, s.seat(on), s.characters);
		const swToken = { characterId: 'scarletwoman', label: 'Is The Demon' };

		it("is data in Lil' Monsta's rules", () => {
			expect(jinxRulesBetween('lilmonsta', 'scarletwoman', committedCharacters())).toEqual({
				carriedBy: { marked: 'Is The Demon' }
			});
		});

		it('holds the game when the babysitter dies with 5 or more alive', () => {
			// Wiki: "If Lil' Monsta dies with 5 or more players alive, the Scarlet Woman babysits Lil'
			// Monsta for the rest of the game."
			const s = base.execute('poisoner');
			expect(gameEnds(s.game, s.characters)).toMatchObject([
				{ rule: 'demon-dead', holds: [{ rule: 'becomes-demon', seats: [s.seat('scarletwoman')] }] }
			]);
			// She takes no Demon character: she babysits instead.
			expect(becomesOffer(s.game, s.seat('scarletwoman'), swToken, s.characters)).toBeUndefined();
			// Not yet marked: the Minions may still pass the baby to anyone.
			expect(misses(s, 'chef')).toEqual([]);
		});

		it('once she is marked, Lil’ Monsta stays with her and nobody else', () => {
			// Wiki: "If Lil' Monsta dies with 5 or more players alive, the Scarlet Woman babysits Lil'
			// Monsta for the rest of the game."
			const s = base.execute('poisoner').reminder('scarletwoman', 'scarletwoman', 'Is The Demon');
			expect(misses(s, 'scarletwoman')).toEqual([]);
			expect(misses(s, 'chef')).toEqual(['jinx']);
			expect(misses(s, 'mayor')).toEqual(['jinx']);
			const token = s.game.seats[s.seat('poisoner')].reminders.find(
				(r) => r.characterId === 'lilmonsta'
			)!;
			const kept = s.do((at) => ({
				type: 'MoveReminder',
				reminderId: token.reminderId,
				toSeatId: at.seat('scarletwoman')
			}));
			expect(gameEnds(kept.game, kept.characters)).toEqual([]);
			// Executing her later ends the game: she is the Demon.
			const executed = kept.newDay().execute('scarletwoman');
			expect(gameEnds(executed.game, executed.characters)).toMatchObject([
				{ rule: 'demon-dead', winner: 'good' }
			]);
		});
	});
});
